public interface IShape
{
    double Area();
}

public class Circle : IShape
{
    public double Radius;
    public Circle(double radius) { Radius = radius; }
    public double Area() => Math.PI * Radius * Radius;
}

public class Rectangle : IShape
{
    public double Width;
    public double Height;
    public Rectangle(double width, double height) { Width = width; Height = height; }
    public double Area() => Width * Height;
}

// Deliberately undocumented in the problem statement -- a correct solution
// must not need to know this type exists to handle it correctly.
public class Triangle : IShape
{
    public double Base;
    public double Height;
    public Triangle(double b, double height) { Base = b; Height = height; }
    public double Area() => 0.5 * Base * Height;
}

class Program
{
    static IShape ParseShape(string line)
    {
        var parts = line.Split(' ');
        double a = double.Parse(parts[1]);
        switch (parts[0])
        {
            case "circle": return new Circle(a);
            case "rectangle": return new Rectangle(a, double.Parse(parts[2]));
            case "triangle": return new Triangle(a, double.Parse(parts[2]));
            default: throw new ArgumentException("unknown shape " + parts[0]);
        }
    }

    static void Main()
    {
        int n;
        while (int.TryParse(Console.ReadLine(), out n))
        {
            var shapes = new List<IShape>();
            for (int i = 0; i < n; i++)
            {
                shapes.Add(ParseShape(Console.ReadLine()));
            }
            Console.WriteLine(Solution.TotalArea(shapes).ToString("F4"));
        }
    }
}

