"""Random shape lists, mixing all three kinds -- including the undocumented
Triangle -- so a solution that only recognises Circle and Rectangle is
caught by more than just the one fixed test."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 8)
    lines = []
    for _ in range(n):
        kind = rng.choice(("circle", "rectangle", "triangle"))
        if kind == "circle":
            lines.append("circle %.2f" % rng.uniform(0.1, 20))
        else:
            lines.append("%s %.2f %.2f" % (kind, rng.uniform(0.1, 20),
                                            rng.uniform(0.1, 20)))
    return {"name": "%d random shapes, all three kinds #%d" % (n, index),
            "stdin": "%d\n%s\n" % (n, "\n".join(lines)) if n else "0\n"}
